(7231389, 1118356, 60173, '<td valign="top">There''s some great stuff going on in the background here.<br/> <br/>If I had edited this, I might have burned the bright bit to the bottom right of the flower and dodged the flower a tad to bring it out. As it is, there''s great color and balance, but the flower gets lost a little for me. <br/> <br/>I hope you don''t mind, I did a really quick edit to show you what I mean. <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1118779" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/60173/120/Copyrighted_Image_Reuse_Prohibited_1118779.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/60173/120/Copyrighted_Image_Reuse_Prohibited_1118779.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/60173/120/Copyrighted_Image_Reuse_Prohibited_1118779.jpg"/></a></td>', 'There''s some great stuff going on in the background here. If I had edited this, I might have burned the bright bit to the bottom right of the flower and dodged the flower a tad to bring it out. As it is, there''s great color and balance, but the flower gets lost a little for me.  I hope you don''t mind, I did a really quick edit to show you what I mean.  ', '2014-06-20 15:32:45.000000', NULL, 1),
(7231408, 1118477, 62076, '<td valign="top">Interesting effect. In camera or in post I wonder.</td>', 'Interesting effect. In camera or in post I wonder.', '2014-06-20 17:29:34.000000', NULL, 1),
(7231409, 1118438, 62076, '<td valign="top">To me this is not enough landscape. The same flower shot from a lower perspective could have work better, letting us see more of the landscape.</td>', 'To me this is not enough landscape. The same flower shot from a lower perspective could have work better, letting us see more of the landscape.', '2014-06-20 17:33:25.000000', NULL, 1),
(7231410, 1118449, 62076, '<td valign="top">This seems to bee more of a soft focus, than a shallow DOF. But it''s hard to say. Awesome location anyway.</td>', 'This seems to bee more of a soft focus, than a shallow DOF. But it''s hard to say. Awesome location anyway.', '2014-06-20 17:38:40.000000', NULL, 1),
(7231468, 1118541, 98339, '<td valign="top">I think you have this reversed...your fence in the FG should have been in clear focus...</td>', 'I think you have this reversed...your fence in the FG should have been in clear focus...', '2014-06-20 22:06:52.000000', NULL, 1),
(7231469, 1118028, 98339, '<td valign="top">not what I would categorize as "landscape"</td>', 'not what I would categorize as "landscape"', '2014-06-20 22:07:45.000000', NULL, 1),
(7231470, 1118438, 98339, '<td valign="top">not exactly what "I" consider as "landscape"...sorry  But on the other hand...you have a very beautiful flower with excellent detail and color what I consider to be Macro</td>', 'not exactly what "I" consider as "landscape"...sorry  But on the other hand...you have a very beautiful flower with excellent detail and color what I consider to be Macro', '2014-06-20 22:09:03.000000', NULL, 1),
(7231471, 1118477, 98339, '<td valign="top">Not my idea of Shallow Depth of Field...sorry</td>', 'Not my idea of Shallow Depth of Field...sorry', '2014-06-20 22:10:20.000000', NULL, 1),
(7231473, 1118329, 98339, '<td valign="top">ya, I think you have this reversed...to bad...</td>', 'ya, I think you have this reversed...to bad...', '2014-06-20 22:15:47.000000', NULL, 1),
(7231485, 1118477, 175946, '<td valign="top">unfortunately, it appears to have some sensor dust spots, sorry</td>', 'unfortunately, it appears to have some sensor dust spots, sorry', '2014-06-20 22:50:55.000000', NULL, 1),
(7231486, 1118028, 175946, '<td valign="top">the lighting is just a little harsh for my taste, the subject matter is great though</td>', 'the lighting is just a little harsh for my taste, the subject matter is great though', '2014-06-20 22:52:04.000000', NULL, 1),
(7231590, 1118325, 62249, '<td valign="top">Pretty.</td>', 'Pretty.', '2014-06-21 13:37:24.000000', NULL, 1),
(7231591, 1117525, 62249, '<td valign="top">Cute! The image tells a happy little story.</td>', 'Cute! The image tells a happy little story.', '2014-06-21 13:39:17.000000', NULL, 1),
(7231592, 1118527, 62249, '<td valign="top">Nice gneiss!</td>', 'Nice gneiss!', '2014-06-21 13:40:26.000000', NULL, 1),
(7231594, 1118445, 62249, '<td valign="top">Nice. I like the detail in the grain.</td>', 'Nice. I like the detail in the grain.', '2014-06-21 13:46:32.000000', NULL, 1),
(7231595, 1118394, 62249, '<td valign="top">Lovely. Nice detail in the fore/midground grain.</td>', 'Lovely. Nice detail in the fore/midground grain.', '2014-06-21 13:47:46.000000', NULL, 1),
(7231596, 1118406, 62249, '<td valign="top">Excellent! Good sharpness on the insects, and good blur in the background.</td>', 'Excellent! Good sharpness on the insects, and good blur in the background.', '2014-06-21 13:48:28.000000', NULL, 1),
(7231597, 1118141, 62249, '<td valign="top">Nice lighting, color, composition.</td>', 'Nice lighting, color, composition.', '2014-06-21 13:49:02.000000', NULL, 1),
(7231598, 1118303, 62249, '<td valign="top">Pretty.</td>', 'Pretty.', '2014-06-21 13:49:50.000000', NULL, 1),
(7231599, 1118312, 62249, '<td valign="top">I like the vertical orientation and how you used the rock to frame the lighthouse.</td>', 'I like the vertical orientation and how you used the rock to frame the lighthouse.', '2014-06-21 13:51:58.000000', NULL, 1),
(7231600, 1118501, 62249, '<td valign="top">Very pretty. An nice mix of concrete and abstract.</td>', 'Very pretty. An nice mix of concrete and abstract.', '2014-06-21 13:52:25.000000', NULL, 1),
(7231602, 1118325, 68504, '<td valign="top">well done.</td>', 'well done.', '2014-06-21 14:06:11.000000', NULL, 1),
(7231604, 1118452, 68504, '<td valign="top">wonderful waves</td>', 'wonderful waves', '2014-06-21 14:07:20.000000', NULL, 1),
(7231709, 1117513, 67258, '<td valign="top">Love the landscape and depth of field, definitely not keen on the infra red pinks.</td>', 'Love the landscape and depth of field, definitely not keen on the infra red pinks.', '2014-06-22 04:48:10.000000', NULL, 1),
(7231710, 1118259, 67258, '<td valign="top">Lovely.</td>', 'Lovely.', '2014-06-22 04:48:33.000000', NULL, 1),
(7231711, 1118450, 67258, '<td valign="top">Very pretty.  Your use of shallow depth of field adds something to the photo - a sense of shimmering heat, and of movement, that would otherwise be missing.</td>', 'Very pretty.  Your use of shallow depth of field adds something to the photo - a sense of shimmering heat, and of movement, that would otherwise be missing.', '2014-06-22 04:49:38.000000', NULL, 1),
(7231712, 1117927, 67258, '<td valign="top">A pretty flower, well separated from its background - but for the purposes of this challenge, too much separation for me.  I get very little sense of the landscape.</td>', 'A pretty flower, well separated from its background - but for the purposes of this challenge, too much separation for me.  I get very little sense of the landscape.', '2014-06-22 04:50:56.000000', NULL, 1),
(7231713, 1118028, 67258, '<td valign="top">This doesn''t work for me in terms of the challenge.  There is little of the landscape here, and the photo is all about the fungi and the shell.  The light odes seem a little ''wrong'', a bit flat.</td>', 'This doesn''t work for me in terms of the challenge.  There is little of the landscape here, and the photo is all about the fungi and the shell.  The light odes seem a little ''wrong'', a bit flat.', '2014-06-22 04:52:38.000000', NULL, 1),
(7231714, 1118252, 67258, '<td valign="top">The photo seems to be all about the woman sitting at the bench, with the landscape very much an aside.  The idea of using the foreground tree to provide a frame was a good one, but I wish that the landscape element wasn''t obscured.</td>', 'The photo seems to be all about the woman sitting at the bench, with the landscape very much an aside.  The idea of using the foreground tree to provide a frame was a good one, but I wish that the landscape element wasn''t obscured.', '2014-06-22 04:54:16.000000', NULL, 1),
(7231715, 1118445, 67258, '<td valign="top">Good technical skills, but the building dominates the scene.  A wider view may have provided more of a sense of landscape and opened the scene up.  As it, I find the composition quite claustrophobic.</td>', 'Good technical skills, but the building dominates the scene.  A wider view may have provided more of a sense of landscape and opened the scene up.  As it, I find the composition quite claustrophobic.', '2014-06-22 04:56:18.000000', NULL, 1),
(7231716, 1118543, 67258, '<td valign="top">A good sense of landscape here.  The shadow on the wood is a bit harsh, but otherwise a good scene.</td>', 'A good sense of landscape here.  The shadow on the wood is a bit harsh, but otherwise a good scene.', '2014-06-22 04:57:10.000000', NULL, 1),
(7231717, 1118352, 67258, '<td valign="top">Not sure about the thistle as your foreground interest.  I find my eyes being pulled in competing directions by the composition, which makes for an uncomfortable viewing experience.</td>', 'Not sure about the thistle as your foreground interest.  I find my eyes being pulled in competing directions by the composition, which makes for an uncomfortable viewing experience.', '2014-06-22 05:00:12.000000', NULL, 1),
(7231718, 1118341, 67258, '<td valign="top">I love puffins!  Nicely done, and good control of exposure with plenty of plumage detail in the blacks.  Shame about the haloing around the rocks - I imagine that it is an artifact side issue with your lens, and therefore little that you can do about it.</td>', 'I love puffins!  Nicely done, and good control of exposure with plenty of plumage detail in the blacks.  Shame about the haloing around the rocks - I imagine that it is an artifact side issue with your lens, and therefore little that you can do about it.', '2014-06-22 05:04:38.000000', NULL, 1),
(7231735, 1118302, 15711, '<td valign="top">Tilt shift really works.  Like a tiny little town. :D</td>', 'Tilt shift really works.  Like a tiny little town. :D', '2014-06-22 09:03:10.000000', NULL, 1),
(7231736, 1118491, 15711, '<td valign="top">I love this. :D</td>', 'I love this. :D', '2014-06-22 09:04:12.000000', NULL, 1),
(7231799, 1118499, 67258, '<td valign="top">Delightful.  The softly two elements - the sharply focused foreground, and the softly out of focus landscape of the background work as one complementing each other.  A perfect use of shallow depth of field in landscape photography.</td>', 'Delightful.  The softly two elements - the sharply focused foreground, and the softly out of focus landscape of the background work as one complementing each other.  A perfect use of shallow depth of field in landscape photography.', '2014-06-22 15:13:43.000000', NULL, 1),
(7231800, 1117999, 67258, '<td valign="top">A strong entry for this challenge.  The shallow depth of field adds to the scene, which is clearly a landscape.</td>', 'A strong entry for this challenge.  The shallow depth of field adds to the scene, which is clearly a landscape.', '2014-06-22 15:17:01.000000', NULL, 1),
(7231801, 1118394, 67258, '<td valign="top">A pleasingly photographed scene.</td>', 'A pleasingly photographed scene.', '2014-06-22 15:17:33.000000', NULL, 1),
(7231802, 1118325, 67258, '<td valign="top">Rather lovely - I can''t dee any part that is sharp, and feel this is more probably soft focus rather than shallow depth of field, though.</td>', 'Rather lovely - I can''t dee any part that is sharp, and feel this is more probably soft focus rather than shallow depth of field, though.', '2014-06-22 15:18:46.000000', NULL, 1),
(7231803, 1118479, 67258, '<td valign="top">Ooh, I do like this!  A superb use of shallow depth of field - the toadstools are placed so beautifully in to the context of their environment, whilst the photo is clearly a landscape (given, with a twist).9.</td>', 'Ooh, I do like this!  A superb use of shallow depth of field - the toadstools are placed so beautifully in to the context of their environment, whilst the photo is clearly a landscape (given, with a twist).9.', '2014-06-22 15:20:54.000000', NULL, 1),
(7232181, 1118265, 118154, '<td valign="top">In my view this is not so much a landscape. Its not a bad image in itself.</td>', 'In my view this is not so much a landscape. Its not a bad image in itself.', '2014-06-23 10:29:36.000000', NULL, 1),
(7232204, 1118287, 114225, '<td valign="top">Unique take on the challenge. I enjoy it.</td>', 'Unique take on the challenge. I enjoy it.', '2014-06-23 11:58:56.000000', NULL, 1),
(7232211, 1118326, 114225, '<td valign="top">Overall the image is ok. I feel like if a graduated filter were used to lighten the ground whir keeping the sky the same, this could be better.</td>', 'Overall the image is ok. I feel like if a graduated filter were used to lighten the ground whir keeping the sky the same, this could be better.', '2014-06-23 12:05:00.000000', NULL, 1),
(7232237, 1118420, 114225, '<td valign="top">I like the thought here, but I don''t like the editing. Feels uneven and sloppy.</td>', 'I like the thought here, but I don''t like the editing. Feels uneven and sloppy.', '2014-06-23 12:57:55.000000', NULL, 1),
(7232239, 1118256, 114225, '<td valign="top">Really nice find. It points to the main attraction.</td>', 'Really nice find. It points to the main attraction.', '2014-06-23 12:58:28.000000', NULL, 1),
(7232240, 1118325, 114225, '<td valign="top">I''m not sure about this. I like the scene and light but the strange softness is off-putiing.</td>', 'I''m not sure about this. I like the scene and light but the strange softness is off-putiing.', '2014-06-23 12:59:21.000000', NULL, 1),
(7232242, 1118162, 114225, '<td valign="top">The detail of this is hidden.</td>', 'The detail of this is hidden.', '2014-06-23 12:59:56.000000', NULL, 1),
(7232243, 1118303, 114225, '<td valign="top">I like how this feels like the beginning of a story.</td>', 'I like how this feels like the beginning of a story.', '2014-06-23 13:00:22.000000', NULL, 1),
(7232244, 1118434, 114225, '<td valign="top">Nice find. The editing left some ugly halos.</td>', 'Nice find. The editing left some ugly halos.', '2014-06-23 13:00:50.000000', NULL, 1),
(7232245, 1118388, 114225, '<td valign="top">Good contrast here.</td>', 'Good contrast here.', '2014-06-23 13:01:05.000000', NULL, 1),
(7232246, 1118517, 114225, '<td valign="top">The purple pops. Too bad the background isn''t more blurred.</td>', 'The purple pops. Too bad the background isn''t more blurred.', '2014-06-23 13:01:57.000000', NULL, 1),
(7232247, 1117999, 114225, '<td valign="top">Nice, similar to one of my outtakes.</td>', 'Nice, similar to one of my outtakes.', '2014-06-23 13:02:22.000000', NULL, 1),
(7232248, 1118356, 114225, '<td valign="top">I really like what the background brings to this.</td>', 'I really like what the background brings to this.', '2014-06-23 13:02:51.000000', NULL, 1),
(7232249, 1118437, 114225, '<td valign="top">My eyes go immediately to the background. That is a good thing with the rather uninteresting foreground.</td>', 'My eyes go immediately to the background. That is a good thing with the rather uninteresting foreground.', '2014-06-23 13:03:40.000000', NULL, 1),
(7232250, 1118450, 114225, '<td valign="top">I feel a sense of approachment in this scene.</td>', 'I feel a sense of approachment in this scene.', '2014-06-23 13:04:20.000000', NULL, 1),
(7232251, 1117489, 114225, '<td valign="top">Not sure about this. Nice colors and moon. But distracting elements.</td>', 'Not sure about this. Nice colors and moon. But distracting elements.', '2014-06-23 13:05:01.000000', NULL, 1),
(7232252, 1118543, 114225, '<td valign="top">I find this to be interesting.</td>', 'I find this to be interesting.', '2014-06-23 13:05:22.000000', NULL, 1),
(7232253, 1118235, 114225, '<td valign="top">Nothing great, nothing terrible. Just average to me.</td>', 'Nothing great, nothing terrible. Just average to me.', '2014-06-23 13:06:01.000000', NULL, 1),
(7232254, 1118271, 114225, '<td valign="top">I like how you captured repeating elements in a nice context.</td>', 'I like how you captured repeating elements in a nice context.', '2014-06-23 13:06:33.000000', NULL, 1),
(7232255, 1118258, 114225, '<td valign="top">Seems like this is the start of a beautiful experience.</td>', 'Seems like this is the start of a beautiful experience.', '2014-06-23 13:07:08.000000', NULL, 1),
(7232256, 1118329, 114225, '<td valign="top">Nicely captured. The guy walking rounds out the composition nicely.</td>', 'Nicely captured. The guy walking rounds out the composition nicely.', '2014-06-23 13:07:41.000000', NULL, 1),
(7232259, 1118535, 114225, '<td valign="top">A bit cliche, but well done.</td>', 'A bit cliche, but well done.', '2014-06-23 13:11:15.000000', NULL, 1),
(7232260, 1117927, 114225, '<td valign="top">I like that there is a true story here.</td>', 'I like that there is a true story here.', '2014-06-23 13:11:37.000000', NULL, 1),
(7232261, 1118493, 114225, '<td valign="top">Looks like we are at the beginning of many "out of frame" type shots.<br/>I do like how the subject and background mix.</td>', 'Looks like we are at the beginning of many "out of frame" type shots.I do like how the subject and background mix.', '2014-06-23 13:12:52.000000', NULL, 1),
(7232270, 1118526, 114225, '<td valign="top">This is effective. Good natural framing.</td>', 'This is effective. Good natural framing.', '2014-06-23 14:19:21.000000', NULL, 1),
(7232271, 1118277, 114225, '<td valign="top">Good balance, but weird processing.</td>', 'Good balance, but weird processing.', '2014-06-23 14:19:50.000000', NULL, 1),
(7232272, 1118116, 114225, '<td valign="top">A bit cliche, but ok.</td>', 'A bit cliche, but ok.', '2014-06-23 14:20:03.000000', NULL, 1),
(7232273, 1118445, 114225, '<td valign="top">I like how you composed this.</td>', 'I like how you composed this.', '2014-06-23 14:20:25.000000', NULL, 1),
(7232274, 1118141, 114225, '<td valign="top">Good use of color.</td>', 'Good use of color.', '2014-06-23 14:20:56.000000', NULL, 1),
(7232275, 1118405, 114225, '<td valign="top">Interesting how the bend looks a bit like a reflection.</td>', 'Interesting how the bend looks a bit like a reflection.', '2014-06-23 14:21:39.000000', NULL, 1),
(7232277, 1118527, 156466, '<td valign="top">Nice perspective, but I''d love to see a little more of the scene beyond the fissure.</td>', 'Nice perspective, but I''d love to see a little more of the scene beyond the fissure.', '2014-06-23 14:38:36.000000', NULL, 1),
(7232278, 1118491, 156466, '<td valign="top">Need more vista to go with the foreground.  Landscape is vista AND/OR orientation, and I see neither.</td>', 'Need more vista to go with the foreground.  Landscape is vista AND/OR orientation, and I see neither.', '2014-06-23 14:41:20.000000', NULL, 1),
(7232279, 1118263, 156466, '<td valign="top">Need more vista to go with the foreground.  Landscape is vista AND/OR orientation, and I see neither.</td>', 'Need more vista to go with the foreground.  Landscape is vista AND/OR orientation, and I see neither.', '2014-06-23 14:42:28.000000', NULL, 1),
(7232280, 1118277, 156466, '<td valign="top">Love the scene in the glass.  Would like to see less structure in the sky behind it.</td>', 'Love the scene in the glass.  Would like to see less structure in the sky behind it.', '2014-06-23 14:43:04.000000', NULL, 1),
(7232281, 1118535, 156466, '<td valign="top">Really nice.</td>', 'Really nice.', '2014-06-23 14:43:29.000000', NULL, 1),
(7232283, 1118312, 156466, '<td valign="top">I''d like to see more of the background in a landscape.  Landscape is vista AND/OR orientation, and I see neither.  Nice photo otherwise.</td>', 'I''d like to see more of the background in a landscape.  Landscape is vista AND/OR orientation, and I see neither.  Nice photo otherwise.', '2014-06-23 14:45:49.000000', NULL, 1),
(7232284, 1118287, 156466, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2014-06-23 14:46:52.000000', NULL, 1),
(7232285, 1118452, 156466, '<td valign="top">Sort of a no depth of field landscape, eh?</td>', 'Sort of a no depth of field landscape, eh?', '2014-06-23 14:47:49.000000', NULL, 1),
(7232286, 1118450, 156466, '<td valign="top">Bring the horizon down and this could have been nice.</td>', 'Bring the horizon down and this could have been nice.', '2014-06-23 14:48:45.000000', NULL, 1),
(7232287, 1118271, 156466, '<td valign="top">Nice composition.  Not crazy about the vintage camera treatment.</td>', 'Nice composition.  Not crazy about the vintage camera treatment.', '2014-06-23 14:50:20.000000', NULL, 1),
(7232288, 1118437, 156466, '<td valign="top">Would almost rather have the mountains in focus.  Too much of nothing distinct in the foreground.</td>', 'Would almost rather have the mountains in focus.  Too much of nothing distinct in the foreground.', '2014-06-23 14:51:04.000000', NULL, 1),
